def parse_csv(raw_csv: str) -> Tuple[List[str], List[List[str]]]:
    """
    Parses a raw CSV string into a dictionary with keys 'columns' and 'rows'.

    Returns:
        (headers, rows): A tuple of (list of strings, list of lists of strings).
        If successful, returns the parsed data.
        Otherwise, raises ValueError.
    """
    # Initialize headers and rows dictionaries
    headers = []
    rows = []

    # Split by delimiter
    lines = raw_csv.splitlines()

    if not lines:
        raise ValueError("Empty CSV input")

    # Handle multi-line headers
    header_lines = []
    for line in lines:
        if line.strip():
            header_lines.append(line)

    # Parse the first line as a header
    if len(header_lines) == 1:
        header_line = header_lines[0]
        # Split by comma, handling quoted fields with escaped quotes
        parts = []
        current_field = ""
        in_quotes = False

        for char in header_line:
            if char == '"':
                if not in_quotes:
                    in_quotes = True
                    current_field += char
                else:
                    current_field += char
                    if char == '\\' and current_field:
                        current_field = current_field.replace("\\", "\\\\")
                    current_field += char
            elif char == ',' and not in_quotes:
                parts.append(current_field.strip())
                current_field = ""
            else:
                current_field += char

        # Handle the last field
        if current_field.strip():
            parts.append(current_field.strip())

        headers = [p.strip() for p in parts]
    else:
        # Split by comma, handling quoted fields with escaped quotes
