        # Handle the last field
        if current_field.strip():
            parts.append(current_field.strip())

        headers = [p.strip() for p in parts]

    # Parse remaining lines as rows
    for line in lines[1:]:
        if not line.strip():
            continue

        row_parts = []
        current_row = []
        in_quotes = False

        for char in line:
            if char == '"':
                if not in_quotes:
                    in_quotes = True
                    current_row.append(char)
                else:
                    current_row.append(char)
                    if char == '\\' and current_row:
                        current_row = current_row.replace("\\", "\\\\")
                    current_row.append(char)
            elif char == ',' and not in_quotes:
                row_parts.append(current_row)
                current_row = []
            else:
                current_row.append(char)

        # Handle the last field of the row
        if current_row:
            row_parts.append(current_row)

        rows.append(row_parts)

    return headers, rows

